// One Slack card per approver of the pending step, built from what Landledger shows (the request and its evidence),
// with Approve and Reject buttons. A button's value carries the request, the step and the hash of what was shown.
const event = $('Step waits on approvers').first().json;
const detail = $input.first().json;
const r = detail.request;
const e = detail.evidence ?? {};
const money = (v) => (v === null || v === undefined ? '—' : `$${Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 })}`);
const per = r.recurrence === 'monthly' ? ' a month' : '';
const lines = (r.evidence?.lines ?? []).map((l) => `• ${l.label}: ${money(l.amount)}`).join('\n');
const links = [...(r.evidence?.links ?? []), ...(r.related ?? []).filter((x) => x.url).map((x) => ({ label: x.type === 'pull_request' ? 'Pull request' : x.type, url: x.url }))]
  .map((l) => `<${l.url}|${l.label}>`).join(' · ');
const who = r.requester?.kind === 'agent' ? `${r.requester.agent.name} (agent), sponsor ${r.requester.sponsor?.name ?? r.requester.sponsor?.email}` : r.requester?.person?.name ?? r.requester?.person?.email;
const value = JSON.stringify({ r: r.id, n: r.number, s: event.step.position, h: detail.evidenceSha256 });
const text = `${r.number}: ${r.title} — ${money(r.amount.amount)}${per} for ${r.costCenter.code}`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${r.number} · ${r.title}`.slice(0, 150) } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Amount*\n${money(r.amount.amount)}${per}` },
    { type: 'mrkdwn', text: `*Cost center*\n${r.costCenter.code} · ${r.costCenter.name}` },
    { type: 'mrkdwn', text: `*Asked by*\n${who}` },
    { type: 'mrkdwn', text: `*Step*\n${event.step.label}${event.step.deadlineAt ? ` (by ${event.step.deadlineAt.slice(0, 10)})` : ''}` },
  ] },
  ...(r.note ? [{ type: 'section', text: { type: 'mrkdwn', text: `> ${r.note.slice(0, 2900)}` } }] : []),
  { type: 'section', text: { type: 'mrkdwn', text: [
    `*The month for ${r.costCenter.code}* (${e.month ?? ''}): spent ${money(e.actual)}, reserved ${money(e.reserved)}, budget ${money(e.budget)}; left after this ${money(e.leftAfter)}.`,
    e.why ? `_${e.why}_` : '', lines, r.evidence?.basis ?? '', links,
  ].filter(Boolean).join('\n').slice(0, 2990) } },
  { type: 'actions', block_id: 'landledger_decision', elements: [
    { type: 'button', action_id: 'landledger_approve', style: 'primary', text: { type: 'plain_text', text: 'Approve' }, value },
    { type: 'button', action_id: 'landledger_reject', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, value,
      confirm: { title: { type: 'plain_text', text: 'Reject?' }, text: { type: 'plain_text', text: 'The requester is told it was rejected in Slack.' }, confirm: { type: 'plain_text', text: 'Reject' }, deny: { type: 'plain_text', text: 'Back' } } },
    { type: 'button', action_id: 'landledger_open', text: { type: 'plain_text', text: 'Open in Landledger' }, url: event.url },
  ] },
];
return (event.approvers ?? []).filter((a) => a.email).map((a) => ({ email: a.email, name: a.name, text, blocks }));

parameters.codeEach:
// The card's new text: the decision Landledger recorded, or why it refused (Relay the decision continues on an error).
const press = JSON.parse($('Button pressed').first().json.value);
const failed = $json.error ? ($json.error.message ?? String($json.error)) : '';
const d = $json.decision;
const text = failed
  ? `\u26a0\ufe0f ${press.n}: Landledger did not take your answer: ${failed}`
  : `${d.outcome === 'approve' ? '\u2705' : '\u274c'} ${$json.request.number} ${d.outcome === 'approve' ? 'approved' : 'rejected'} by ${d.person.name} \u00b7 ${$json.request.title}`;
return { text, blocks: [{ type: 'section', text: { type: 'mrkdwn', text } }] };
